package com.rikkeibank.transaction.service;
import com.rikkeibank.common.events.TransferEvent;import com.rikkeibank.transaction.domain.BankTransaction;import com.rikkeibank.transaction.repo.TransactionRepository;import org.junit.jupiter.api.*;import org.springframework.kafka.core.KafkaTemplate;import java.math.BigDecimal;import java.util.UUID;import java.util.concurrent.CompletableFuture;import static org.assertj.core.api.Assertions.*;import static org.mockito.ArgumentMatchers.*;import static org.mockito.Mockito.*;
class TransferSagaServiceTest{private TransactionRepository repo;private AccountOperations accounts;private KafkaTemplate<String,TransferEvent> kafka;private TransferSagaService service;@BeforeEach void setup(){repo=mock(TransactionRepository.class);accounts=mock(AccountOperations.class);kafka=mock(KafkaTemplate.class);when(repo.save(any())).thenAnswer(i->i.getArgument(0));when(kafka.send(anyString(),anyString(),any())).thenReturn(CompletableFuture.completedFuture(null));service=new TransferSagaService(repo,accounts,kafka,true);}
 @Test void completesDebitAndCredit(){UUID source=UUID.randomUUID(),target=UUID.randomUUID(),customer=UUID.randomUUID();BankTransaction tx=service.transfer(source,target,customer,new BigDecimal("25.00"),false);assertThat(tx.getStatus()).isEqualTo(BankTransaction.Status.COMPLETED);verify(accounts).debit(tx.getId(),source,customer,new BigDecimal("25.00"));verify(accounts).credit(tx.getId(),target,customer,new BigDecimal("25.00"));verify(accounts,never()).refund(any(),any(),any(),any());}
 @Test void compensatesWhenCreditStepFails(){UUID source=UUID.randomUUID(),target=UUID.randomUUID(),customer=UUID.randomUUID();doThrow(new IllegalStateException("credit down")).when(accounts).credit(any(),eq(target),eq(customer),any());BankTransaction tx=service.transfer(source,target,customer,new BigDecimal("10"),false);assertThat(tx.getStatus()).isEqualTo(BankTransaction.Status.COMPENSATED);verify(accounts).refund(tx.getId(),source,customer,new BigDecimal("10.00"));verify(kafka,atLeastOnce()).send(eq("bank.transfer.events"),eq(tx.getId().toString()),argThat(e->e.status().equals("COMPENSATED")));}
 @Test void demoFailureInjectionAlsoCompensates(){BankTransaction tx=service.transfer(UUID.randomUUID(),UUID.randomUUID(),UUID.randomUUID(),BigDecimal.ONE,true);assertThat(tx.getStatus()).isEqualTo(BankTransaction.Status.COMPENSATED);verify(accounts).refund(eq(tx.getId()),any(),any(),eq(new BigDecimal("1.00")));}}

